// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket(100);

        address alice = address(0x1);
        vm.prank(alice);
        c.getFreeKilo();

        vm.warp(block.timestamp + 1 days);

        address bob = address(0x2);
        vm.prank(bob);
        c.getFreeKilo();
        vm.warp(block.timestamp + 1 days);
        vm.prank(bob);
        c.collectDrugs(bob);

        vm.warp(block.timestamp + 1 days);
        vm.prank(bob);
        c.collectDrugs(alice);

        address ref = c.referrals(bob);
        assertTrue(ref == bob, "Bug: referral overwritten");
    }
}
